-- 198 optional ORIGINAL listening comprehension activities in 66 published Grade1-3 lessons, 22 Arab countries.
-- Each activity contains independent teacher script, one safe question, options and private database answer.
-- Browser voice depends on an Arabic speech synthesis voice installed on the device; teacher mode remains available.
-- NO recorded audio files or external paid speech provider claimed. Do not infer ministerial alignment.
BEGIN;
SET LOCAL statement_timeout='90s';
SET LOCAL lock_timeout='5s';
CREATE TEMP TABLE dadyoom_listening_198_templates ON COMMIT DROP AS
SELECT grade::int,activity_order::int,activity_type::text,title::text,section::text,prompt::text,content::jsonb,answer::jsonb
FROM jsonb_to_recordset($listening$[{"grade":1,"activity_order":4,"activity_type":"listening","title":"استمع إلى الترتيب","section":"listening","prompt":"ما الخطوة الأولى التي سمعتها؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"استمع جيدًا. افتح دفتر اللغة العربية. ثم اكتب اسمك أعلى الصفحة. بعد ذلك ضع القلم على الطاولة.","listeningQuestion":"ما الخطوة الأولى التي سمعتها؟","options":["افتح دفتر اللغة العربية","ضع القلم على الطاولة","اكتب اسمك أعلى الصفحة"],"grade":1,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"افتح دفتر اللغة العربية"}},{"grade":1,"activity_order":5,"activity_type":"listening","title":"استمع إلى التفاصيل","section":"listening","prompt":"بأي لون طلبت التعليمات تلوين الدائرة؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"أمسك بطاقة الوردة. ضع دائرة حول كلمة وردة، ثم لوّن الدائرة بالأخضر. أخيرًا أعد البطاقة إلى المعلم.","listeningQuestion":"بأي لون طلبت التعليمات تلوين الدائرة؟","options":["الأحمر","الأخضر","الأصفر"],"grade":1,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"الأخضر"}},{"grade":1,"activity_order":6,"activity_type":"listening","title":"استمع وافهم التعليمات","section":"listening","prompt":"ما التعليمات التي جاءت بين رفع اليد والنظر إلى السبورة؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"أرفع يدي مرة واحدة. ثم أضع يدي على الطاولة. وبعد ذلك أنظر إلى السبورة.","listeningQuestion":"ما التعليمات التي جاءت بين رفع اليد والنظر إلى السبورة؟","options":["أضع يدي على الطاولة","أغلق باب الصف","أقفز مرتين"],"grade":1,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"أضع يدي على الطاولة"}},{"grade":2,"activity_order":4,"activity_type":"listening","title":"استمع إلى الترتيب","section":"listening","prompt":"متى تكتب التاريخ وفق التعليمات المسموعة؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"افتح الدفتر أولًا، ثم ارسم نجمة صغيرة أعلى الصفحة. بعد رسم النجمة اكتب التاريخ تحتها، وأخيرًا راجع ترتيب الخطوات.","listeningQuestion":"متى تكتب التاريخ وفق التعليمات المسموعة؟","options":["قبل فتح الدفتر","بعد رسم النجمة","بعد مراجعة جميع الخطوات فقط"],"grade":2,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"بعد رسم النجمة"}},{"grade":2,"activity_order":5,"activity_type":"listening","title":"استمع إلى التفاصيل","section":"listening","prompt":"ماذا تفعل إذا لم تجد كلمة مكتبة على البطاقة؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"إذا وجدت كلمة مكتبة على البطاقة فضع خطًا تحتها. وإذا لم تجدها، ارفع يدك لتطلب بطاقة أخرى. لا تكتب جوابًا قبل التأكد من الكلمة.","listeningQuestion":"ماذا تفعل إذا لم تجد كلمة مكتبة على البطاقة؟","options":["أطلب بطاقة أخرى برفع اليد","أضع خطًا تحت كلمة مختلفة","أغلق الدفتر وأنهي النشاط"],"grade":2,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"أطلب بطاقة أخرى برفع اليد"}},{"grade":2,"activity_order":6,"activity_type":"listening","title":"استمع وافهم التعليمات","section":"listening","prompt":"ما الصورة المطلوبة في الموضع الثاني؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"ضع صورة الشجرة أولًا، ثم صورة الكتاب ثانيًا، وأخيرًا صورة التفاحة. انظر إلى ترتيب البطاقات قبل أن تخبر زميلك بأنك انتهيت.","listeningQuestion":"ما الصورة المطلوبة في الموضع الثاني؟","options":["صورة التفاحة","صورة الكتاب","صورة الشجرة"],"grade":2,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"صورة الكتاب"}},{"grade":3,"activity_order":4,"activity_type":"listening","title":"استمع إلى الترتيب","section":"listening","prompt":"أين تضع بطاقة شجرة وفق التعليمات؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"استمع إلى الشرط: إذا بدأت البطاقة بحرف الميم فضعها في العمود الأول، وإلا فضعها في العمود الثاني. بطاقة مدرسة تبدأ بالميم، أما بطاقة شجرة فتبدأ بالشين.","listeningQuestion":"أين تضع بطاقة شجرة وفق التعليمات؟","options":["في العمود الأول","في العمود الثاني","خارج الجدول"],"grade":3,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"في العمود الثاني"}},{"grade":3,"activity_order":5,"activity_type":"listening","title":"استمع إلى التفاصيل","section":"listening","prompt":"ما الخطوة التي تأتي مباشرة بعد كتابة الفقرة؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"قبل كتابة الفقرة، اختر عنوانًا واضحًا. بعد كتابة الفقرة، راجع علامات الترقيم، وإذا وجدت خطأ صححه. أخيرًا اقرأ الفقرة بصوت مسموع لزميلك.","listeningQuestion":"ما الخطوة التي تأتي مباشرة بعد كتابة الفقرة؟","options":["مراجعة علامات الترقيم","اختيار عنوان جديد","قراءة الفقرة للمعلم قبل المراجعة"],"grade":3,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"مراجعة علامات الترقيم"}},{"grade":3,"activity_order":6,"activity_type":"listening","title":"استمع وافهم التعليمات","section":"listening","prompt":"ما الإجراء المطلوب عند اختلاف أعضاء الفريق؟","content":{"origin":"DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030","requiresTeacherRead":true,"text":"كوّن فريقًا من ثلاثة طلاب. يقرأ الطالب الأول السؤال، ويسجل الثاني إجابة الفريق، ويتحقق الثالث من وجود الدليل في النص. إذا اختلف الفريق، أعيدوا قراءة الجملة قبل اتخاذ القرار.","listeningQuestion":"ما الإجراء المطلوب عند اختلاف أعضاء الفريق؟","options":["اختيار إجابة عشوائية","إعادة قراءة الجملة والبحث عن الدليل","إيقاف جميع أنشطة الصف"],"grade":3,"audioEvidence":"browser-voice-if-installed-or-teacher-read; no recorded audio","editorialScope":"original self-contained supplementary formative listening"},"answer":{"correct":"إعادة قراءة الجملة والبحث عن الدليل"}}]$listening$::jsonb)
AS x(grade int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE eligible int;history_count int;inserted int;
BEGIN
 IF (SELECT count(*) FROM pg_temp.dadyoom_listening_198_templates)<>9
 OR (SELECT count(DISTINCT (grade,activity_order)) FROM pg_temp.dadyoom_listening_198_templates)<>9
 OR EXISTS(SELECT 1 FROM pg_temp.dadyoom_listening_198_templates
  WHERE activity_type<>'listening' OR length(content->>'text')<65
  OR (content->>'requiresTeacherRead')<>'true' OR content->>'listeningQuestion' IS NULL
  OR content ? 'correct' OR content ? 'answer' OR answer IS NULL)
 THEN RAISE EXCEPTION 'Invalid non-leaking teacher-listening content'; END IF;
 WITH c AS (
  SELECT l.id,l.content,count(a.id) FILTER(WHERE a.is_published) n,
  count(DISTINCT a.activity_order) orders,max(a.activity_order) maxorder
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
  LEFT JOIN public.lesson_activities a ON a.lesson_id=l.id
  WHERE l.title='الاستماع واتباع التعليمات' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3
  GROUP BY l.id,l.content)
 SELECT count(*) INTO eligible FROM c WHERE n=3 AND orders=3 AND maxorder=3
 AND length(content)>1900 AND content LIKE '%الاستماع%' AND content LIKE '%التعليمات%';
 IF eligible<>66 THEN RAISE EXCEPTION 'Expected 66 unchanged teacher-script lessons, got %',eligible; END IF;
 SELECT count(*) INTO history_count
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 WHERE l.title='الاستماع واتباع التعليمات' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3
 AND (EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
 OR EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
 OR EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id));
 IF history_count<>0 THEN RAISE EXCEPTION 'Learner history appeared in % listening lessons, abort',history_count; END IF;
 IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_G123_LISTENING_NEW_198_ORIGINAL_TTS_OPTIONAL_20261030')
 THEN RAISE EXCEPTION 'Idempotency: original listening activity batch already installed'; END IF;
 INSERT INTO public.lesson_activities
 (lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
 SELECT l.id,t.title,t.activity_type,'استمع إلى النص ثم أجب عن السؤال المسموع؛ لا تقرأ نص المعلم أولًا.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN pg_temp.dadyoom_listening_198_templates t ON t.grade=g.grade_number
 WHERE l.title='الاستماع واتباع التعليمات' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3
 AND length(l.content)>1900 AND l.content LIKE '%الاستماع%' AND l.content LIKE '%التعليمات%';
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>198 THEN RAISE EXCEPTION 'Atomic rollback: expected 198 listening activities, inserted %',inserted; END IF;
 RAISE NOTICE 'DADYOOM_G123_OPTIONAL_LISTENING_ACTIVITIES=%',inserted;
END $safe$;
COMMIT;
